create table if not exists admins (id uuid primary key default gen_random_uuid(), email text unique not null, created_at timestamptz default now());
create table if not exists customers (id uuid primary key default gen_random_uuid(), name text not null, phone text not null, address text not null, notes text, created_at timestamptz default now());
create table if not exists categories (id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null);
create table if not exists collections (id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null, description text, banner_url text, featured boolean default false, sort_order int default 0);
create table if not exists products (id uuid primary key default gen_random_uuid(), category_id uuid references categories(id), name text not null, slug text unique not null, description text, price int not null, stock int default 0, featured boolean default false, out_of_stock boolean default false, created_at timestamptz default now());
create table if not exists product_images (id uuid primary key default gen_random_uuid(), product_id uuid references products(id) on delete cascade, image_url text not null, sort_order int default 0);
create table if not exists product_collections (product_id uuid references products(id) on delete cascade, collection_id uuid references collections(id) on delete cascade, primary key(product_id, collection_id));
create table if not exists homepage_sections (id uuid primary key default gen_random_uuid(), type text not null, title text, subtitle text, media_url text, active boolean default true, sort_order int default 0, payload jsonb default '{}'::jsonb);
create table if not exists orders (id uuid primary key default gen_random_uuid(), order_number text unique not null, customer_id uuid references customers(id), status text not null default 'pending', total_amount int not null, created_at timestamptz default now());
create table if not exists order_items (id uuid primary key default gen_random_uuid(), order_id uuid references orders(id) on delete cascade, product_id uuid references products(id), quantity int not null, unit_price int not null);
create table if not exists settings (id uuid primary key default gen_random_uuid(), key text unique not null, value jsonb not null default '{}'::jsonb);
create table if not exists whatsapp_settings (id uuid primary key default gen_random_uuid(), whatsapp_number text not null, order_template text, validation_template text, updated_at timestamptz default now());
